          <div class="df-email-tabs"><button type="button" class="df-email-tab is-active" data-email-audience="admin"><?php echo Text::_('COM_DECAROFORMS_PREVIEW_ADMIN'); ?></button><button type="button" class="df-email-tab" data-email-audience="user"><?php echo Text::_('COM_DECAROFORMS_PREVIEW_USER'); ?></button></div>
          <div class="df-email-subject"><small><?php echo Text::_('COM_DECAROFORMS_EMAIL_PREVIEW_SUBJECT'); ?></small><strong id="df-email-preview-subject"></strong></div>
          <div class="df-email-canvas" id="df-email-preview-canvas"></div>
        </div>
        <div class="df-email-modal-actions"><button class="df-btn" type="button" data-email-close><?php echo Text::_('COM_DECAROFORMS_CLOSE'); ?></button><button class="df-btn df-primary" type="button" id="df-email-use-template"><?php echo Text::_('COM_DECAROFORMS_USE_TEMPLATE'); ?></button></div>
      </div>
    </div>

    <div class="df-bactions" style="justify-content:flex-end"><a class="df-btn" href="<?php echo $this->formsUrl; ?>"><?php echo Text::_('COM_DECAROFORMS_CANCEL'); ?></a><button class="df-btn df-primary" type="submit"><?php echo Text::_('COM_DECAROFORMS_SAVE_FORM'); ?></button></div>
    <?php echo HTMLHelper::_('form.token'); ?>
  </form>
  <?php echo FormHelper::footer(); ?>
</div>
<script>
(()=>{
const tr=<?php echo json_encode([
'add'=>Text::_('COM_DECAROFORMS_ADD'),'empty'=>Text::_('COM_DECAROFORMS_NO_FIELDS_SELECTED'),'options'=>Text::_('COM_DECAROFORMS_OPTIONS_ONE_LINE'),'moveUp'=>Text::_('COM_DECAROFORMS_MOVE_UP'),'moveDown'=>Text::_('COM_DECAROFORMS_MOVE_DOWN'),'remove'=>Text::_('COM_DECAROFORMS_REMOVE'),'label'=>Text::_('COM_DECAROFORMS_LABEL'),'key'=>Text::_('COM_DECAROFORMS_FIELD_KEY'),'type'=>Text::_('COM_DECAROFORMS_TYPE'),'placeholder'=>Text::_('COM_DECAROFORMS_PLACEHOLDER'),'help'=>Text::_('COM_DECAROFORMS_HELP_TEXT'),'required'=>Text::_('COM_DECAROFORMS_REQUIRED_FIELD'),
'cats'=>['personal'=>Text::_('COM_DECAROFORMS_CATEGORY_PERSONAL'),'contact'=>Text::_('COM_DECAROFORMS_CATEGORY_CONTACT'),'address'=>Text::_('COM_DECAROFORMS_CATEGORY_ADDRESS'),'organisation'=>Text::_('COM_DECAROFORMS_CATEGORY_ORGANISATION'),'sport'=>Text::_('COM_DECAROFORMS_CATEGORY_SPORT'),'event'=>Text::_('COM_DECAROFORMS_CATEGORY_EVENT'),'message'=>Text::_('COM_DECAROFORMS_CATEGORY_MESSAGE'),'document'=>Text::_('COM_DECAROFORMS_CATEGORY_DOCUMENT'),'consent'=>Text::_('COM_DECAROFORMS_CATEGORY_CONSENT'),'custom'=>Text::_('COM_DECAROFORMS_CATEGORY_CUSTOM')],
'types'=>['text'=>Text::_('COM_DECAROFORMS_TYPE_TEXT'),'email'=>Text::_('COM_DECAROFORMS_TYPE_EMAIL'),'tel'=>Text::_('COM_DECAROFORMS_TYPE_TEL'),'number'=>Text::_('COM_DECAROFORMS_TYPE_NUMBER'),'date'=>Text::_('COM_DECAROFORMS_TYPE_DATE'),'time'=>Text::_('COM_DECAROFORMS_TYPE_TIME'),'textarea'=>Text::_('COM_DECAROFORMS_TYPE_TEXTAREA'),'select'=>Text::_('COM_DECAROFORMS_TYPE_SELECT'),'radio'=>Text::_('COM_DECAROFORMS_TYPE_RADIO'),'checkboxes'=>Text::_('COM_DECAROFORMS_TYPE_CHECKBOXES'),'consent'=>Text::_('COM_DECAROFORMS_TYPE_CONSENT'),'file'=>Text::_('COM_DECAROFORMS_TYPE_FILE')]
],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
const library=<?php echo json_encode($this->library,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
let selected=<?php echo json_encode($initialFields,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
let statuses=<?php echo json_encode($initialStatuses,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
let columns=<?php echo json_encode($initialColumns,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
const lib=document.getElementById('df-library'),sel=document.getElementById('df-selected'),search=document.getElementById('df-library-search'),filter=document.getElementById('df-library-filter'),hidden=document.getElementById('df-fields-json'),statusesHidden=document.getElementById('df-statuses-json'),columnsHidden=document.getElementById('df-columns-json'),statusEditor=document.getElementById('df-status-editor'),columnList=document.getElementById('df-column-list');
const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
function uniqueKey(base){base=String(base||'field').replace(/[^a-zA-Z0-9_]+/g,'_').replace(/^_+|_+$/g,'').toLowerCase()||'field';let k=base,n=2;while(selected.some(x=>x.key===k))k=base+'_'+n++;return k;}
function add(item){const x=JSON.parse(JSON.stringify(item));x.key=uniqueKey(x.key);x.options=x.options||[];selected.push(x);renderSelected();}
function renderLibrary(){const q=(search.value||'').toLowerCase(),cat=filter.value;lib.innerHTML='';library.filter(x=>(cat==='all'||x.category===cat)&&(!q||(x.label+' '+x.key+' '+x.type).toLowerCase().includes(q))).forEach((x,i)=>{const d=document.createElement('div');d.className='df-lib-item';d.innerHTML=`<div><strong>${esc(x.label)}</strong><small>${esc(tr.cats[x.category]||x.category)} · ${esc(tr.types[x.type]||x.type)}</small></div><button class="df-add" type="button">${esc(tr.add)}</button>`;d.querySelector('button').onclick=()=>add(x);lib.appendChild(d);});}
function update(i,k,v){selected[i][k]=v;sync();}
function renderSelected(){sel.innerHTML='';if(!selected.length){sel.innerHTML='<div class="df-selected-empty">'+esc(tr.empty)+'</div>';sync();renderColumns();return;}selected.forEach((x,i)=>{const options=['select','radio','checkboxes'].includes(x.type)?`<div class="full"><label>${esc(tr.options)}</label><textarea data-k="options">${esc((x.options||[]).join('\n'))}</textarea></div>`:'';const d=document.createElement('div');d.className='df-selected-item';d.innerHTML=`<div class="df-selected-top"><div><strong>${i+1}. ${esc(x.label)}</strong><div class="df-note">${esc(tr.types[x.type]||x.type)} · ${esc(tr.key)}: ${esc(x.key)}</div></div><div class="df-mini-actions"><button type="button" data-act="up" title="${esc(tr.moveUp)}">↑</button><button type="button" data-act="down" title="${esc(tr.moveDown)}">↓</button><button type="button" data-act="remove" title="${esc(tr.remove)}">×</button></div></div><div class="df-selected-config"><div><label>${esc(tr.label)}</label><input data-k="label" value="${esc(x.label)}"></div><div><label>${esc(tr.key)}</label><input data-k="key" value="${esc(x.key)}"></div><div><label>${esc(tr.type)}</label><select data-k="type">${['text','email','tel','number','date','time','textarea','select','radio','checkboxes','consent','file'].map(t=>`<option value="${esc(t)}" ${t===x.type?'selected':''}>${esc(tr.types[t]||t)}</option>`).join('')}</select></div><div><label>${esc(tr.placeholder)}</label><input data-k="placeholder" value="${esc(x.placeholder||'')}"></div><div class="full"><label>${esc(tr.help)}</label><input data-k="help" value="${esc(x.help||'')}"></div>${options}<div class="full df-required"><input type="checkbox" data-k="required" ${x.required?'checked':''}><label>${esc(tr.required)}</label></div></div>`;
 d.querySelectorAll('[data-k]').forEach(el=>{el.addEventListener('input',()=>{const k=el.dataset.k;if(k==='required')selected[i][k]=el.checked;else if(k==='options')selected[i][k]=el.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);else selected[i][k]=el.value;sync();if(k==='label')renderColumns();});if(el.dataset.k==='type')el.addEventListener('change',()=>renderSelected());});
 d.querySelector('[data-act="up"]').onclick=()=>{if(i>0){[selected[i-1],selected[i]]=[selected[i],selected[i-1]];renderSelected();}};d.querySelector('[data-act="down"]').onclick=()=>{if(i<selected.length-1){[selected[i+1],selected[i]]=[selected[i],selected[i+1]];renderSelected();}};d.querySelector('[data-act="remove"]').onclick=()=>{selected.splice(i,1);renderSelected();};sel.appendChild(d);});sync();renderColumns();}
function slugStatus(v){return String(v||'status').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,30)||'status';}
const statusPalette=['#0d6efd','#f59e0b','#198754','#6c757d','#dc3545','#7c3aed','#0891b2'];
function defaultStatusColor(key,index){const known={new:'#0d6efd',processing:'#f59e0b',replied:'#198754',closed:'#6c757d',spam:'#dc3545'};return known[key]||statusPalette[index%statusPalette.length];}
function renderStatuses(){statusEditor.innerHTML='';statuses.forEach((st,i)=>{st.color=/^#[0-9a-fA-F]{6}$/.test(st.color||'')?st.color:defaultStatusColor(st.key||'',i);const r=document.createElement('div');r.className='df-status-row';r.innerHTML=`<input data-status-label placeholder="<?php echo htmlspecialchars(Text::_('COM_DECAROFORMS_STATUS_LABEL'),ENT_QUOTES,'UTF-8'); ?>" value="${esc(st.label||'')}"><input data-status-key placeholder="key" value="${esc(st.key||'')}"><div class="df-status-color-wrap"><input class="df-status-color" data-status-color type="color" value="${esc(st.color)}" title="<?php echo htmlspecialchars(Text::_('COM_DECAROFORMS_STATUS_COLOR'),ENT_QUOTES,'UTF-8'); ?>" aria-label="<?php echo htmlspecialchars(Text::_('COM_DECAROFORMS_STATUS_COLOR'),ENT_QUOTES,'UTF-8'); ?>"><span class="df-status-color-value">${esc(st.color)}</span></div><button type="button" class="df-status-remove" title="${esc(tr.remove)}">×</button>`;const li=r.querySelector('[data-status-label]'),ki=r.querySelector('[data-status-key]'),ci=r.querySelector('[data-status-color]'),cv=r.querySelector('.df-status-color-value');li.addEventListener('input',()=>{statuses[i].label=li.value;if(!statuses[i].key){statuses[i].key=slugStatus(li.value);ki.value=statuses[i].key;}sync();});ki.addEventListener('input',()=>{statuses[i].key=slugStatus(ki.value);sync();});ci.addEventListener('input',()=>{statuses[i].color=ci.value.toLowerCase();cv.textContent=statuses[i].color;sync();});r.querySelector('button').onclick=()=>{if(statuses.length>1){statuses.splice(i,1);renderStatuses();}};statusEditor.appendChild(r);});sync();}
function renderColumns(){const standard=[['_reference','<?php echo addslashes(Text::_('COM_DECAROFORMS_REFERENCE')); ?>'],['_email','<?php echo addslashes(Text::_('COM_DECAROFORMS_EMAIL')); ?>'],['_status','<?php echo addslashes(Text::_('COM_DECAROFORMS_STATUS')); ?>'],['_created_at','<?php echo addslashes(Text::_('COM_DECAROFORMS_DATE')); ?>']];const items=[...standard,...selected.map(x=>[x.key,x.label])];columnList.innerHTML='';items.forEach(([key,label])=>{const d=document.createElement('label');d.className='df-column-item';d.innerHTML=`<input type="checkbox" value="${esc(key)}" ${columns.includes(key)?'checked':''}><span>${esc(label)}</span>`;d.querySelector('input').addEventListener('change',e=>{if(e.target.checked){if(!columns.includes(key))columns.push(key);}else columns=columns.filter(x=>x!==key);sync();});columnList.appendChild(d);});columns=columns.filter(k=>items.some(i=>i[0]===k));if(!columns.length)columns=['_reference'];sync();}
function sync(){hidden.value=JSON.stringify(selected);statusesHidden.value=JSON.stringify(statuses);columnsHidden.value=JSON.stringify(columns);}

const emailModal=document.getElementById('df-email-modal'),emailCanvas=document.getElementById('df-email-preview-canvas'),emailSubject=document.getElementById('df-email-preview-subject'),emailTemplateName=document.getElementById('df-email-template-name'),emailUse=document.getElementById('df-email-use-template'),emailAdminSelect=document.querySelector('[name="email_template_admin"]'),emailUserSelect=document.querySelector('[name="email_template_user"]');
const emailTemplateNames=<?php echo json_encode(['standard'=>Text::_('COM_DECAROFORMS_TEMPLATE_STANDARD'),'minimal'=>Text::_('COM_DECAROFORMS_TEMPLATE_MINIMAL'),'institutional'=>Text::_('COM_DECAROFORMS_TEMPLATE_INSTITUTIONAL'),'card'=>Text::_('COM_DECAROFORMS_TEMPLATE_CARD'),'compact'=>Text::_('COM_DECAROFORMS_TEMPLATE_COMPACT')],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
const emailLabels=<?php echo json_encode(['yes'=>Text::_('JYES'),'selected'=>Text::_('COM_DECAROFORMS_TEMPLATE_SELECTED'),'use'=>Text::_('COM_DECAROFORMS_USE_TEMPLATE')],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
let emailTemplate='standard',emailAudience='admin';
function emailValue(field){const key=String(field.key||'').toLowerCase(),type=String(field.type||'text');const map={first_name:'Mario',last_name:'Rossi',full_name:'Mario Rossi',birth_date:'15/05/1990',email:'mario.rossi@example.com',phone:'+39 333 123 4567',address:'Via Roma',street_number:'10',postcode:'00100',city:'Roma',country:'Italia',organisation:'Organizzazione esempio',club:'Associazione esempio',role:'Referente',member_number:'12345',sport:'Pallavolo',team_name:'Squadra esempio',event_date:'15/09/2026',arrival_date:'15/09/2026',departure_date:'16/09/2026',participants:'2',subject:'Richiesta informazioni',message:'Questo è un testo di esempio inviato tramite il modulo.',notes:'Nota di esempio',motivation:'Testo di esempio.',attachment:'documento.pdf',identity_document:'documento-identita.pdf',photo:'foto.jpg',payment_proof:'ricevuta.pdf'};if(map[key])return map[key];if(Array.isArray(field.options)&&field.options.length)return String(field.options[0]);if(type==='consent')return emailLabels.yes;if(type==='file')return 'documento.pdf';if(type==='date')return '03/09/2026';if(type==='time')return '10:30';if(type==='number')return '1';if(type==='email')return 'mario.rossi@example.com';if(type==='tel')return '+39 333 123 4567';return 'Esempio';}
function emailRowsHtml(){return selected.map(field=>`<tr><td style="padding:8px 10px;border-bottom:1px solid #e6e9ed;color:#68717d;width:40%;font-size:13px">${esc(field.label||field.key)}</td><td style="padding:8px 10px;border-bottom:1px solid #e6e9ed;color:#17202a;font-weight:600;font-size:13px">${esc(emailValue(field))}</td></tr>`).join('')||'<tr><td style="padding:12px;color:#68717d">—</td></tr>';}
function emailCurrentSelect(){return emailAudience==='user'?emailUserSelect:emailAdminSelect;}
function emailMarkCards(){const active=emailCurrentSelect()?.value||'';document.querySelectorAll('[data-email-template]').forEach(card=>card.classList.toggle('is-active',card.dataset.emailTemplate===active));}
function emailRender(){const title=(document.querySelector('[name="title"]')?.value||'Modulo').trim()||'Modulo';const rawSubject=(emailAudience==='user'?document.querySelector('[name="email_subject_user"]')?.value:document.querySelector('[name="email_subject_admin"]')?.value)||'';const fallback=emailAudience==='user'?'Abbiamo ricevuto il tuo invio – {form_title}':'Nuovo invio – {form_title}';const subject=(rawSubject.trim()||fallback).replaceAll('{form_title}',title);const intro=emailAudience==='user'?`Abbiamo ricevuto correttamente il tuo invio per <strong>${esc(title)}</strong>.`:`È stato ricevuto un nuovo invio dal modulo <strong>${esc(title)}</strong>.`;const rows=emailRowsHtml(),ref='FRM-20260903-DEMO',accent='#e60046',dark='#182433';emailSubject.textContent=subject;emailTemplateName.textContent=emailTemplateNames[emailTemplate]||emailTemplate;let html='';if(emailTemplate==='minimal'){html=`<div style="max-width:680px;background:#fff;padding:24px;font-family:Arial,sans-serif;color:#17202a"><h2 style="margin:0 0 9px;font-size:22px">${esc(subject)}</h2><p style="margin:0 0 14px;line-height:1.55">${intro}</p><div style="margin-bottom:12px;font-size:12px;color:#68717d">Riferimento: <strong style="color:#17202a">${ref}</strong></div><table style="width:100%;border-collapse:collapse">${rows}</table></div>`;}else if(emailTemplate==='institutional'){html=`<div style="max-width:680px;background:#fff;font-family:Arial,sans-serif;color:#17202a"><div style="background:${dark};padding:22px 24px"><h2 style="margin:0;color:#fff;font-size:23px">${esc(subject)}</h2></div><div style="padding:20px 24px"><p style="margin:0 0 14px;line-height:1.55">${intro}</p><div style="padding:9px 11px;background:#f2f4f6;margin-bottom:12px;font-size:12px">Riferimento: <strong>${ref}</strong></div><table style="width:100%;border-collapse:collapse">${rows}</table></div></div>`;}else if(emailTemplate==='card'){html=`<div style="max-width:680px;background:#eef1f4;padding:22px;font-family:Arial,sans-serif;color:#17202a"><div style="background:#fff;border:1px solid #dfe3e8;border-radius:8px;padding:22px"><h2 style="margin:0 0 10px;color:${accent};font-size:23px">${esc(subject)}</h2><p style="margin:0 0 14px;line-height:1.55">${intro}</p><div style="padding:9px 11px;border:1px solid #e1e5e9;border-radius:5px;margin-bottom:12px;font-size:12px">Riferimento: <strong>${ref}</strong></div><table style="width:100%;border-collapse:collapse">${rows}</table></div></div>`;}else if(emailTemplate==='compact'){html=`<div style="max-width:620px;background:#fff;border-left:6px solid ${accent};padding:18px 20px;font-family:Arial,sans-serif;color:#17202a"><h2 style="margin:0 0 8px;font-size:20px">${esc(subject)}</h2><p style="margin:0 0 10px;line-height:1.45;font-size:13px">${intro}</p><div style="margin-bottom:9px;font-size:11px;color:#68717d">Riferimento: <strong>${ref}</strong></div><table style="width:100%;border-collapse:collapse">${rows}</table></div>`;}else{html=`<div style="max-width:680px;background:#fff;border-radius:6px;overflow:hidden;font-family:Arial,sans-serif;color:#17202a"><div style="height:8px;background:${accent}"></div><div style="padding:22px 24px"><h2 style="margin:0 0 10px;font-size:24px">${esc(subject)}</h2><p style="margin:0 0 14px;line-height:1.55">${intro}</p><div style="padding:9px 11px;background:#f2f4f6;border-radius:4px;margin-bottom:12px;font-size:12px">Riferimento: <strong>${ref}</strong></div><table style="width:100%;border-collapse:collapse">${rows}</table></div></div>`;}emailCanvas.innerHTML=html;emailMarkCards();emailUse.textContent=(emailCurrentSelect()?.value===emailTemplate)?emailLabels.selected:emailLabels.use;}
function emailOpen(template){emailTemplate=template||'standard';emailAudience='admin';document.querySelectorAll('[data-email-audience]').forEach(x=>x.classList.toggle('is-active',x.dataset.emailAudience===emailAudience));emailModal.hidden=false;document.body.style.overflow='hidden';emailRender();}
function emailClose(){emailModal.hidden=true;document.body.style.overflow='';}
document.querySelectorAll('[data-email-template]').forEach(card=>card.addEventListener('click',()=>emailOpen(card.dataset.emailTemplate)));
document.querySelectorAll('[data-email-close]').forEach(btn=>btn.addEventListener('click',emailClose));
document.querySelectorAll('[data-email-audience]').forEach(btn=>btn.addEventListener('click',()=>{emailAudience=btn.dataset.emailAudience||'admin';document.querySelectorAll('[data-email-audience]').forEach(x=>x.classList.toggle('is-active',x===btn));emailRender();}));
emailUse.addEventListener('click',()=>{const select=emailCurrentSelect();if(select){select.value=emailTemplate;select.dispatchEvent(new Event('change',{bubbles:true}));}emailRender();});
[emailAdminSelect,emailUserSelect,document.querySelector('[name="email_subject_admin"]'),document.querySelector('[name="email_subject_user"]'),document.querySelector('[name="title"]')].filter(Boolean).forEach(el=>el.addEventListener('input',()=>{if(!emailModal.hidden)emailRender();}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!emailModal.hidden)emailClose();});

document.getElementById('df-add-status').onclick=()=>{statuses.push({key:'',label:'',color:statusPalette[statuses.length%statusPalette.length]});renderStatuses();};
const templates={contact:['full_name','email','subject','message','privacy_consent'],registration:['first_name','last_name','email','phone','birth_date','organisation','notes','privacy_consent'],event:['first_name','last_name','email','phone','event_date','participants','notes','privacy_consent'],membership:['first_name','last_name','birth_date','email','phone','address','postcode','city','club','member_number','sport','identity_document','privacy_consent'],reservation:['first_name','last_name','email','phone','arrival_date','departure_date','participants','notes','privacy_consent'],blank:[]};
document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{const names=templates[b.dataset.template]||[];selected=names.map(n=>JSON.parse(JSON.stringify(library.find(x=>x.key===n)))).filter(Boolean);renderSelected();});
search.addEventListener('input',renderLibrary);filter.addEventListener('change',renderLibrary);document.getElementById('df-builder-form').addEventListener('submit',sync);renderLibrary();renderSelected();renderStatuses();renderColumns();
})();
</script>
